function mergeLayout(base, patch) {
  const out = { ...base };
  for (const [k2, v] of Object.entries(patch)) {
    const b = out[k2];
    out[k2] = v && typeof v === "object" && !Array.isArray(v) && b && typeof b === "object" ? mergeLayout(b, v) : v;
  }
  return out;
}

