    discard: { x: 773, y: 293 },
    // slot-0 landing point, nudged further RIGHT to widen the gap (was 748)
    discardFan: 3,
    discardFanDx: -54,
    // matches the hand's maxStep so the discard overlaps exactly like the player's hand
    discardFanDy: 0,
    // pure-horizontal fan (no vertical drop) so it reads as a row sitting in the tray
