    discardPlate: { x: 719, y: 360, w: 220, h: 76 },
    // Matching pedestal behind the single deck stack (ui-deck-plate, master 363×179 ~2.03:1), centred on
    // the deck and levelled to the same tray line (`y`) as the discard plate so both piles sit on a shelf.
    deckPlate: { x: 522, y: 360, w: 150, h: 74 },
    // Pile count labels (Deck: N / Discard: N) ride the tray banners: `deckLabelY`/`discardLabelY` are the
