    ribbon: { dy: -106, w: 422, h: 74 },
    emblem: { dy: -180 },
    crown: { w: 132, h: 67 },
    heart: { w: 92, h: 74 },
    verdict: { dy: -115, writeFrac: 0.564, span: 0.3, dir: -1, fontSize: 34, strokeColor: "#2a0f0a", strokeThickness: 4 },
    // The skin's FLYER dress of the same popup (POPUP_PRINT; render/result). DESIGN px — result.ts runs them through
