    badgeBg: 658448,
    iconOutline: 16513004,
    attackIcon: 14174778,
    attackNum: "#ff8a7e",
    healIcon: 4637802,
    healNum: "#7ef0a8",
    // Card mana badge: water-drop icons (mana this card MINTS) tinted with manaFill; a mana-BURN card
    // (J/Q/K/A) shows the flame icon tinted burnFlame instead. (burnFlameCore kept for optional accents.)
    burnFlame: 16742938,
    burnFlameCore: 16765498,
    // A card FROZEN by the foe's Lock spell: darkened (multiply tint) rather than faded, so it still
