  "tutorial.skip": "\u041F\u0440\u043E\u043F\u0443\u0441\u0442\u0438\u0442\u0438",
  "tutorial.next": "\u0414\u0430\u043B\u0456",
  "tutorial.playNow": "\u0414\u043E\u0433\u0440\u0430\u0442\u0438 \u0434\u0443\u0435\u043B\u044C",
  "tutorial.hp.title": "\u0417\u0434\u043E\u0440\u043E\u0432'\u044F",
  "tutorial.hp.body": "\u0422\u0432\u043E\u0454 \u043B\u0456\u0432\u043E\u0440\u0443\u0447, \u0432\u043E\u0440\u043E\u0436\u0435 \u043F\u0440\u0430\u0432\u043E\u0440\u0443\u0447. \u041E\u0431\u043D\u0443\u043B\u0438 \u0432\u043E\u0440\u043E\u0436\u0435 \u2014 \u0456 \u043F\u0435\u0440\u0435\u043C\u043E\u0433\u0430.",
  "tutorial.hand.title": "\u0422\u0432\u043E\u0457 \u043A\u0430\u0440\u0442\u0438",
  "tutorial.hand.body": "\u0422\u0430\u043F\u043D\u0438 \u043A\u0430\u0440\u0442\u0438, \u0442\u043E\u0434\u0456 \xAB\u0413\u0440\u0430\u0442\u0438\xBB. \u0420\u0430\u0437\u043E\u043C \u0456\u0434\u0443\u0442\u044C \u043E\u0434\u043D\u0430 \u043C\u0430\u0441\u0442\u044C, \u043E\u0434\u0438\u043D \u0440\u0430\u043D\u0433 \u0447\u0438 \u043F\u043E\u0441\u043B\u0456\u0434\u043E\u0432\u043D\u0456\u0441\u0442\u044C \u2014 \u0449\u043E \u0431\u0456\u043B\u044C\u0448\u0435 \u043A\u0430\u0440\u0442 \u0437\u0430 \u0445\u0456\u0434, \u0442\u043E \u0431\u0456\u043B\u044C\u0448\u0435 \u0448\u043A\u043E\u0434\u0438.",
  // The card-effect legend on that same coach card (sword / drop / flame icons).
  "tutorial.hand.dmg": "\u041D\u0435\u043F\u0430\u0440\u043D\u0456 \u043A\u0430\u0440\u0442\u0438 \u0431'\u044E\u0442\u044C \u0432\u043E\u0440\u043E\u0433\u0430.",
  "tutorial.hand.heal": "\u041F\u0430\u0440\u043D\u0456 \u043B\u0456\u043A\u0443\u044E\u0442\u044C \u0442\u0435\u0431\u0435.",
  "tutorial.hand.burn": "\u0422, \u0412, \u0414, \u041A \u0449\u0435 \u0439 \u043F\u0430\u043B\u044F\u0442\u044C\n\u043C\u0430\u043D\u0443 \u0432\u043E\u0440\u043E\u0433\u0430.",
  "tutorial.mana.title": "\u041C\u0430\u043D\u0430",
  "tutorial.mana.body": "\u041F\u043E\u043F\u043E\u0432\u043D\u044E\u0454\u0442\u044C\u0441\u044F \u0449\u043E\u0445\u043E\u0434\u0443. \u0412\u0438\u0442\u0440\u0430\u0442\u044C \u0457\u0457 \u043D\u0430 \u041A\u043B\u0438\u043D\u043E\u043A, \u0449\u043E\u0431 \u0431\u0438\u0442\u0438 \u0441\u0438\u043B\u044C\u043D\u0456\u0448\u0435.",
  "tutorial.ult.title": "\u0422\u0432\u0456\u0439 \u0443\u043B\u044C\u0442",
  "tutorial.ult.body": "\u0423 \u0441\u043C\u0443\u0437\u0456 \u0437\u0430\u043A\u043B\u044F\u0442\u044C \u0449\u043E\u0439\u043D\u043E \u0437\u0430\u0441\u0432\u0456\u0442\u0438\u0432\u0441\u044F \u0443\u043B\u044C\u0442 \u0442\u0432\u043E\u0433\u043E \u0433\u0435\u0440\u043E\u044F \u2014 \u0443\u0436\u0435 \u0437\u0430\u0440\u044F\u0434\u0436\u0435\u043D\u0438\u0439. \u0422\u0430\u043F\u043D\u0438, \u0449\u043E\u0431 \u0432\u0433\u0430\u0442\u0438\u0442\u0438 \u0432\u043E\u0440\u043E\u0433\u0430, \u0430 \u0442\u043E\u0434\u0456 \u0433\u0440\u0430\u0439 \u043A\u0430\u0440\u0442\u0438.",
  "spectate.title": "\u041F\u0440\u0438\u0454\u0434\u043D\u0430\u0442\u0438\u0441\u044F \u0434\u043E \u0434\u0443\u0435\u043B\u0456",
