  "adventure.node.dice": "\u041A\u0440\u043E\u043B\u044F\u0447\u0438\u0439 \u0433\u043E\u0434\u0438\u043D\u043D\u0438\u043A",
  "adventure.node.jump": "\u0417\u0440\u0456\u0437\u043A\u0430",
  "adventure.node.slide": "\u0412\u0456\u0434\u043A\u0430\u0442",
  "adventure.desc.wonder": "\u0429\u043E\u0441\u044C \u0442\u0430\u043C \u0454. \u0429\u043E \u0441\u0430\u043C\u0435 - \u0434\u0456\u0437\u043D\u0430\u0454\u0448\u0441\u044F, \u043A\u043E\u043B\u0438 \u043D\u0430\u0441\u0442\u0443\u043F\u0438\u0448.",
  "adventure.wonder.door": "\u041E\u0444\u0456\u0441\u043D\u0435 \u0417\u0430\u0434\u0437\u0435\u0440\u043A\u0430\u043B\u043B\u044F",
  "adventure.wonder.keys": "\u041A\u043B\u044E\u0447\u0456: {n}/{m}",
  "adventure.wonder.hint": "\u0417\u0430 \u0434\u0437\u0435\u0440\u043A\u0430\u043B\u043E\u043C \u043A\u043E\u0436\u043D\u0430 \u043A\u0430\u0440\u0442\u0430 \u0434\u0456\u0454 \u044F\u043A \u0441\u0432\u043E\u044F \u043F\u0440\u043E\u0442\u0438\u043B\u0435\u0436\u043D\u0456\u0441\u0442\u044C: \u0442\u0443\u0437 \u2014 \u0446\u0435 \u0434\u0432\u0456\u0439\u043A\u0430, \u043A\u043E\u0440\u043E\u043B\u044C \u2014 \u0442\u0440\u0456\u0439\u043A\u0430, \u0434\u0430\u043C\u0430 \u2014 \u0447\u0435\u0442\u0432\u0456\u0440\u043A\u0430 \u0456 \u0442\u0430\u043A \u0434\u0430\u043B\u0456. \u0423\u043B\u044C\u0442\u0430 \u0437\u0430\u0440\u044F\u0434\u0436\u0430\u0454\u0442\u044C\u0441\u044F \u0432\u0456\u0434 \u0407\u0425\u041D\u0406\u0425 \u043A\u0430\u0440\u0442. \u0429\u0435\u0434\u0440\u0456\u0448\u0456 \u0441\u043A\u0440\u0438\u043D\u0456. \u041E\u0434\u0438\u043D \u043F\u0440\u043E\u0445\u0456\u0434.",
  "adventure.wonder.leave": "\u041F\u043E\u043A\u0438\u043D\u0443\u0442\u0438",
  "adventure.wonder.leave.title": "\u0412\u0438\u0439\u0442\u0438 \u0437 \u0434\u0437\u0435\u0440\u043A\u0430\u043B\u0430?",
  "adventure.wonder.leave.body": "\u0414\u0432\u0435\u0440\u0456 \u0437\u0430\u0447\u0438\u043D\u044F\u0442\u044C\u0441\u044F \u0437\u0430 \u0442\u043E\u0431\u043E\u044E: \u043F\u0440\u043E\u0445\u0456\u0434 \u0437\u0430\u043A\u0456\u043D\u0447\u0438\u0442\u044C\u0441\u044F \u0442\u0443\u0442, \u0430 \u0432\u0438\u0442\u0440\u0430\u0447\u0435\u043D\u0456 \u043A\u043B\u044E\u0447\u0456 \u043D\u0435 \u043F\u043E\u0432\u0435\u0440\u043D\u0443\u0442\u044C\u0441\u044F. \u0421\u0430\u043C\u0430 \u0433\u043B\u0430\u0432\u0430 \u0447\u0435\u043A\u0430\u0454 \u0442\u0430\u043C, \u0434\u0435 \u0442\u0438 \u0457\u0457 \u043B\u0438\u0448\u0438\u0432.",
  "adventure.wonder.how": "\u041A\u043E\u0436\u0435\u043D \u0431\u043E\u0441, \u044F\u043A\u043E\u0433\u043E \u0442\u0438 \u0437\u0434\u043E\u043B\u0430\u0432 \u043D\u0430 \u0446\u044C\u043E\u043C\u0443 \u043F\u043E\u0432\u0435\u0440\u0441\u0456, \u043B\u0438\u0448\u0430\u0454 \u043A\u043B\u044E\u0447. \u0414\u0432\u0435\u0440\u0456 \u0432\u0456\u0434\u043C\u0438\u043A\u0430\u044E\u0442\u044C {m} \u2014 \u0443 \u0442\u0435\u0431\u0435 {n}.",
  "adventure.wonderTitle": "\u0417\u0430\u0434\u0437\u0435\u0440\u043A\u0430\u043B\u043B\u044F {n}",
  "adventure.story.wonder.title": "\u041A\u0440\u0456\u0437\u044C \u0434\u0437\u0435\u0440\u043A\u0430\u043B\u043E",
  "adventure.story.wonder.body": "\u041F\u043E\u0432\u0435\u0440\u0445 \u0442\u043E\u0439 \u0441\u0430\u043C\u0438\u0439. \u0421\u0442\u043E\u043B\u0438 \u0441\u0442\u043E\u044F\u0442\u044C, \u0434\u0435 \u0441\u0442\u043E\u044F\u043B\u0438. \u0422\u0456\u043B\u044C\u043A\u0438 \u0432\u0441\u0435 \u043D\u0430 \u043D\u0438\u0445 \u043D\u0430\u0432\u0438\u0432\u043E\u0440\u0456\u0442, \u0456 \u043D\u0456\u043A\u043E\u0433\u043E \u0446\u0435, \u0437\u0434\u0430\u0454\u0442\u044C\u0441\u044F, \u043D\u0435 \u0431\u0435\u043D\u0442\u0435\u0436\u0438\u0442\u044C.\n\n\u041A\u043E\u043B\u043E\u0434\u0430 \u0447\u0438\u0442\u0430\u0454\u0442\u044C\u0441\u044F \u0437 \u0456\u043D\u0448\u043E\u0433\u043E \u043A\u0456\u043D\u0446\u044F: \u0442\u0443\u0437 \u0431'\u0454 \u044F\u043A \u0434\u0432\u0456\u0439\u043A\u0430, \u0434\u0432\u0456\u0439\u043A\u0430 \u2014 \u044F\u043A \u0442\u0443\u0437, \u043A\u043E\u0440\u043E\u043B\u044C \u2014 \u044F\u043A \u0442\u0440\u0456\u0439\u043A\u0430, \u0434\u0430\u043C\u0430 \u2014 \u044F\u043A \u0447\u0435\u0442\u0432\u0456\u0440\u043A\u0430. \u0412\u0456\u0441\u0456\u043C\u043A\u0430 \u043B\u0438\u0448\u0430\u0454\u0442\u044C\u0441\u044F \u0441\u043E\u0431\u043E\u044E, \u0431\u043E \u0457\u0439 \u043D\u0456\u043A\u0443\u0434\u0438 \u0434\u0437\u0435\u0440\u043A\u0430\u043B\u0438\u0442\u0438\u0441\u044C. \u0423\u043B\u044C\u0442\u0430 \u0437\u0430\u0440\u044F\u0434\u0436\u0430\u0454\u0442\u044C\u0441\u044F \u0432\u0456\u0434 \u0407\u0425\u041D\u0406\u0425 \u043A\u0430\u0440\u0442, \u043D\u0435 \u0432\u0456\u0434 \u0442\u0432\u043E\u0457\u0445. \u0421\u043A\u0440\u0438\u043D\u0456 \u0449\u0435\u0434\u0440\u0456\u0448\u0456, \u0430 \u0434\u0432\u0435\u0440\u0435\u0439 \u043F\u043E\u0437\u0430\u0434\u0443 \u0432\u0436\u0435 \u043D\u0435\u043C\u0430: \u043E\u0434\u0438\u043D \u043F\u0440\u043E\u0445\u0456\u0434, \u043F\u043E\u043A\u0438 \u043D\u0435 \u0432\u043F\u0430\u0434\u0435 \u0431\u043E\u0441.",
  // Коротка версія — те, що показуємо на вході у дзеркало. Повний текст лишається за кнопкою "i".
  "adventure.story.wonder.short": "\u041A\u043E\u043B\u043E\u0434\u0430 \u0447\u0438\u0442\u0430\u0454\u0442\u044C\u0441\u044F \u0437 \u0456\u043D\u0448\u043E\u0433\u043E \u043A\u0456\u043D\u0446\u044F: \u0442\u0443\u0437 \u0431'\u0454 \u044F\u043A \u0434\u0432\u0456\u0439\u043A\u0430, \u043A\u043E\u0440\u043E\u043B\u044C \u2014 \u044F\u043A \u0442\u0440\u0456\u0439\u043A\u0430. \u0423\u043B\u044C\u0442\u0430 \u0437\u0430\u0440\u044F\u0434\u0436\u0430\u0454\u0442\u044C\u0441\u044F \u0432\u0456\u0434 \u0407\u0425\u041D\u0406\u0425 \u043A\u0430\u0440\u0442.\n\n\u041E\u0434\u0438\u043D \u043F\u0440\u043E\u0445\u0456\u0434, \u043F\u043E\u043A\u0438 \u043D\u0435 \u0432\u043F\u0430\u0434\u0435 \u0431\u043E\u0441. \u041F\u043E\u0434\u0440\u043E\u0431\u0438\u0446\u0456 \u2014 \u043F\u0456\u0434 \xABi\xBB.",
  "adventure.story.wonder.line": "\xAB\u041F\u0438\u043B\u044C\u043D\u0443\u0439 \u0434\u0437\u0435\u0440\u043A\u0430\u043B\u043E. \u0412\u043E\u043D\u043E \u043F\u0438\u043B\u044C\u043D\u0443\u0454 \u0442\u0435\u0431\u0435.\xBB",
