  "minigame.tic-tac-toe.hint": "\u041E\u0431\u0456\u0433\u0440\u0430\u0439 \u043A\u043B\u0435\u0440\u043A\u0430: \u0442\u0440\u0438 \u0441\u0438\u043D\u0456 \u043F\u043B\u0438\u0442\u043A\u0438 \u0432 \u0440\u044F\u0434. \u041D\u0456\u0447\u0438\u044F \u043D\u0435 \u0440\u0430\u0445\u0443\u0454\u0442\u044C\u0441\u044F.",
  "minigame.count-reds.name": "\u041F\u043E\u0440\u0430\u0445\u0443\u0439 \u0447\u0435\u0440\u0432\u043E\u043D\u0456",
  "minigame.count-reds.hint": "\u0417\u0430\u043F\u0430\u043C\u02BC\u044F\u0442\u0430\u0439 \u043A\u0430\u0440\u0442\u0438 \u0439 \u0441\u043A\u0430\u0436\u0438, \u0441\u043A\u0456\u043B\u044C\u043A\u0438 \u0431\u0443\u043B\u043E \u0447\u0435\u0440\u0432\u043E\u043D\u0438\u0445.",
  "minigame.whack.name": "\u041F\u0440\u0438\u0431\u0438\u0439 \u043A\u043B\u0435\u0440\u043A\u0430",
  "minigame.whack.hint": "\u0422\u0430\u043F\u0430\u0439 \u043F\u0456\u0434\u0441\u0432\u0456\u0447\u0435\u043D\u0443 \u043A\u043B\u0456\u0442\u0438\u043D\u0443, \u0434\u043E\u043A\u0438 \u043D\u0435 \u0437\u0433\u0430\u0441\u043B\u0430, - \u0434\u0435\u0441\u044F\u0442\u044C \u0440\u0430\u0437\u0456\u0432.",
  "minigame.sort-ranks.name": "\u0420\u043E\u0437\u043A\u043B\u0430\u0434\u0438 \u0441\u043F\u0440\u0430\u0432\u0438",
  "minigame.sort-ranks.hint": "\u0422\u0430\u043F\u043D\u0438 \u0434\u0432\u0456 \u043F\u043B\u0438\u0442\u043A\u0438, \u0449\u043E\u0431 \u043F\u043E\u043C\u0456\u043D\u044F\u0442\u0438 \u0457\u0445 \u043C\u0456\u0441\u0446\u044F\u043C\u0438. \u0412\u0456\u0434 \u043C\u0435\u043D\u0448\u043E\u0433\u043E \u0434\u043E \u0431\u0456\u043B\u044C\u0448\u043E\u0433\u043E.",
  "minigame.odd-one-out.name": "\u0417\u0430\u0439\u0432\u0438\u0439",
