  "rules.colMana": "\u041C\u0430\u043D\u0430",
  "rules.manaHint": "\u0413\u0440\u0430\u044E\u0447\u0438 \u043A\u0430\u0440\u0442\u0438, \u0432\u0438 \u0441\u0442\u0432\u043E\u0440\u044E\u0454\u0442\u0435 \u043C\u0430\u043D\u0443 \u2014 \u043C\u0435\u043D\u0448\u0456 \u043A\u0430\u0440\u0442\u0438 \u0434\u0430\u044E\u0442\u044C \u0431\u0456\u043B\u044C\u0448\u0435. \u0412\u0438\u0442\u0440\u0430\u0447\u0430\u0439\u0442\u0435 \u0457\u0457 \u043D\u0430 \u0441\u043F\u0435\u043B\u0438. +{up} \u043C\u0430\u043D\u0438 \u0449\u043E\u0445\u043E\u0434\u0443, \u043C\u0430\u043A\u0441\u0438\u043C\u0443\u043C {cap}.",
  "rules.spellsTitle": "\u0421\u043F\u0435\u043B\u0438:",
