  "rules.combos.burn": "\u2212{n} \u043C\u0430\u043D\u0438 \u0432\u043E\u0440\u043E\u0433\u0443",
  "rules.combos.hint": "\u041F\u043E\u043A\u0435\u0440\u043D\u0430 \u043A\u043E\u043C\u0431\u0456\u043D\u0430\u0446\u0456\u044F \u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0446\u0435 \u043F\u043E\u043D\u0430\u0434 \u0435\u0444\u0435\u043A\u0442 \u0441\u0430\u043C\u0438\u0445 \u043A\u0430\u0440\u0442. \u0424\u041B\u0415\u0428 \u0434\u043E\u0434\u0430\u0454 \u043C\u0430\u043D\u0443 \u0432\u0430\u043C, \u0430 \u0421\u0422\u0420\u0418\u0422 \u043D\u0430\u0442\u043E\u043C\u0456\u0441\u0442\u044C \u043F\u0430\u043B\u0438\u0442\u044C \u043C\u0430\u043D\u0443 \u0432\u043E\u0440\u043E\u0433\u0430 \u2014 \u0456 \u0437\u0456\u0431\u0440\u0430\u043D\u0456 \u043D\u0430 \u0432\u0441\u0456\u0445 \u043F\u2019\u044F\u0442\u0438 \u043A\u0430\u0440\u0442\u0430\u0445 \u043E\u0431\u0438\u0434\u0432\u0430 \u043F\u043B\u0430\u0442\u044F\u0442\u044C \u0443\u0434\u0432\u0456\u0447\u0456 \u0431\u0456\u043B\u044C\u0448\u0435. \u0414\u0432\u0456 \u043A\u043E\u043C\u0431\u0456\u043D\u0430\u0446\u0456\u0457 \u2014 \u0443\u043B\u044E\u0431\u043B\u0435\u043D\u0456 \u0443 \u0432\u0430\u0448\u043E\u0433\u043E \u0433\u0435\u0440\u043E\u044F: \u0442\u0430\u043C \u0432\u0456\u043D \u0431\u0435\u0440\u0435 \u0437\u043D\u0430\u0447\u043D\u043E \u0431\u0456\u043B\u044C\u0448\u0435, \u0430 \u043A\u043E\u043C\u0431\u043E \u0437 \u043A\u0430\u0440\u0442\u043E\u044E \u0439\u043E\u0433\u043E \u043C\u0430\u0441\u0442\u0456 \u0449\u0435 \u0439 \u0441\u0438\u043B\u044C\u043D\u0456\u0448\u0435 \u0431\u2019\u0454 \u0442\u0430 \u043B\u0456\u043A\u0443\u0454.",
  "rules.combos.broadway": "\u0420\u044F\u0434 10-\u0412-\u0414-\u041A-\u0422 \u043F\u043B\u0430\u0442\u0438\u0442\u044C \u0442\u0440\u044C\u043E\u043C\u0430 \u0448\u043B\u044F\u0445\u0430\u043C\u0438: \u043C\u0456\u0448\u0430\u043D\u0456 \u043A\u043E\u043B\u044C\u043E\u0440\u0438 \u2014 \u0413\u0440\u0430\u043D\u0434-\u0441\u0442\u0440\u0438\u0442, \u0443\u0441\u0456 \u0447\u0435\u0440\u0432\u043E\u043D\u0456 \u0430\u0431\u043E \u0432\u0441\u0456 \u0447\u043E\u0440\u043D\u0456 \u2014 \u0421\u0435\u043C\u0456-\u0444\u043B\u0435\u0448-\u0440\u043E\u044F\u043B\u044C, \u043E\u0434\u043D\u0430 \u043C\u0430\u0441\u0442\u044C \u2014 \u0424\u043B\u0435\u0448-\u0440\u043E\u044F\u043B\u044C. \u0426\u0456 \u0442\u0440\u0438 \u0442\u0430 \u0441\u0442\u0440\u0438\u0442-\u0444\u043B\u0435\u0448 \u0449\u0435 \u0439 \u041F\u0410\u041B\u042F\u0422\u042C \u043C\u0430\u043D\u0443 \u0432\u043E\u0440\u043E\u0433\u0430.",
