var _baseScreen = null;
var _lastTrack = null;
var _lastMul = 1;
var TURN_WARNING_AT = 5;
var TICK_BASE_RATE = 1.55;
var TICK_RATE_STEP = 0.09;
var TICK_VOL = 0.35;
var COMBO_PITCH_STEP = 0.06;
var _comboStep = 0;
function _rollTrack(pool) {
  if (pool.length <= 1) return pool[0];
  const choices = pool.filter((id) => id !== _lastTrack);
  return choices[Math.floor(Math.random() * choices.length)];
}
function setBaseMusic(screen3) {
  _baseScreen = screen3;
  const track = screen3 === "menu" ? _rollTrack(MENU_TRACKS) : screen3 === "battle" ? _rollTrack(BATTLE_TRACKS) : null;
  _lastTrack = track;
  playMusic(track);
}
function initAudio(scene2) {
  _scene = scene2;
  _musicVol = _loadVol(MUSIC_VOL_KEY, MUSIC_VOL_DEFAULT);
  _sfxVol = _loadVol(SFX_VOL_KEY, SFX_VOL_DEFAULT);
}
function initAudioBus() {
  on("combo:played", ({ effect, burned }) => {
    play("card-place");
    _comboStep = 0;
    if (effect.damage) play("hit-damage");
    else if (effect.heal) play("hit-heal");
    if (burned > 0) play("hit-burn");
  });
  on("card:drawn", () => play("card-draw"));
  on("discard:landed", () => {
    play("card-discard", { rate: 1 + Math.min(4, _comboStep) * COMBO_PITCH_STEP });
    _comboStep++;
  });
  on("discard:reshuffled", () => play("card-shuffle"));
  on("duel:end", ({ winner }) => {
    const localWon = winner != null && winner === localSide();
    fadeMusicThenJingle(localWon ? "sfx-victory" : "sfx-defeat");
  });
  on("turn:changed", ({ side, turnNo }) => {
    if (turnNo <= 1) _lastMul = 1;
    if (side === localSide()) play("turn-yours");
    const mul = G.duel.dmgMul;
    if (mul > _lastMul + 1e-6) play("escalation-step");
    _lastMul = mul;
    if (_baseScreen !== "battle") setBaseMusic("battle");
  });
  on("turn:tick", ({ side, remaining }) => {
    if (side !== localSide()) return;
    if (remaining === TURN_WARNING_AT) play("turn-warning");
    else if (remaining > 0 && remaining < TURN_WARNING_AT) {
      play("ui-click", { rate: TICK_BASE_RATE + (TURN_WARNING_AT - remaining) * TICK_RATE_STEP, volume: TICK_VOL });
    }
  });
  on("ult:fired", () => duckMusic());
  on("menu:open", () => setBaseMusic("menu"));
  on("adventure:visible", ({ shown }) => {
    if (shown && _baseScreen !== "menu") setBaseMusic("menu");
  });
  setBaseMusic("menu");
}

