function loadTinted(scene2, shape, files, dir = "assets/ui") {
  const bake = SKIN_TINT_BAKES?.[shape];
  if (!bake) {
    for (const [key2, file] of Object.entries(files)) scene2.load.image(key2, `${dir}/${file}`);
    return;
  }
  const master = `ui-${shape}--master`;
  scene2.load.once(`filecomplete-image-${master}`, () => bakeTints(scene2, master, bake));
  scene2.load.image(master, `${dir}/${shape}.png`);
}
function bakeTints(scene2, master, tints) {
  const src = scene2.textures.get(master).getSourceImage();
  for (const [key2, tint] of Object.entries(tints)) {
    const c = document.createElement("canvas");
    c.width = src.width;
    c.height = src.height;
    const g = c.getContext("2d");
    g.drawImage(src, 0, 0);
    g.globalCompositeOperation = "multiply";
    g.fillStyle = `#${tint.toString(16).padStart(6, "0")}`;
    g.fillRect(0, 0, c.width, c.height);
    g.globalCompositeOperation = "destination-in";
    g.drawImage(src, 0, 0);
    if (scene2.textures.exists(key2)) scene2.textures.remove(key2);
    scene2.textures.addCanvas(key2, c);
  }
}
