// src/render/card-sprite.ts
var RANK_LABEL = { 1: "A", 11: "J", 12: "Q", 13: "K", [JOKER]: "JK" };
var SUIT_LETTER = { spades: "S", clubs: "C", hearts: "H", diamonds: "D" };
function suitTint(suit) {
  return suit === "hearts" || suit === "diamonds" ? TABLE.color.suitTintRed : TABLE.color.suitTintBlack;
}
function rankLabel(rank) {
  return RANK_LABEL[rank] ?? String(rank);
}
