// src/render/icon-line.ts
var FRAME = {
  "\u25CF": currencyFrame("coin"),
  "\u{1F48E}": currencyFrame("emerald")
};
var DIE_MARK = "\u2682";
var DIE_FACE = 3;
var HEART_MARK = "\u2764";
function createIconLine(scene2, str, o) {
  const iconSz = o.iconSize ?? 22;
  const gap = o.gap ?? 2;
  const tokens = str.split(/(●|💎|⚂|❤)/u).filter((s) => s !== "");
  const texts = [];
  const pieces = [];
  for (const tok of tokens) {
    if (tok === DIE_MARK) {
      const img = scene2.add.image(0, 0, bakeDie(scene2, DIE_FACE)).setOrigin(0, 0.5).setDisplaySize(iconSz, iconSz);
      pieces.push({ obj: img, w: iconSz + gap * 2, pad: gap });
    } else if (tok === HEART_MARK) {
      const img = scene2.add.image(0, 0, ICON.heartFull).setOrigin(0, 0.5).setDisplaySize(iconSz, iconSz);
      pieces.push({ obj: img, w: iconSz + gap * 2, pad: gap });
    } else if (tok in FRAME) {
      const img = scene2.add.image(0, 0, CURRENCY_TEX, FRAME[tok]).setOrigin(0, 0.5).setDisplaySize(iconSz, iconSz);
      pieces.push({ obj: img, w: iconSz + gap * 2, pad: gap });
    } else {
      const txt = scene2.add.text(0, 0, tok, { fontSize: o.fontSize, color: o.color, ...o.fontStyle ? { fontStyle: o.fontStyle } : {} }).setOrigin(0, 0.5);
      texts.push(txt);
      pieces.push({ obj: txt, w: txt.width, pad: 0 });
    }
  }
  const width = pieces.reduce((s, p) => s + p.w, 0);
  let cur2 = -width / 2;
  for (const p of pieces) {
    p.obj.x = cur2 + p.pad;
    cur2 += p.w;
  }
  const container = scene2.add.container(
    0,
    0,
    pieces.map((p) => p.obj)
  );
  return {
    container,
    width,
    setColor(c) {
      for (const txt of texts) txt.setColor(c);
    }
  };
}

