// src/render/fx.ts
init_define_PG_BANNERS();
var PUNCH = 1.12;
var PUNCH_MS = 70;
function buildFx(scene2) {
  function fly(card, from, to, delay, fromScale) {
    const toScale = TABLE.card.playerScale;
    const spr = makeCardSprite(scene2, { ...card, faceUp: true }, from.x, from.y, fromScale).setDepth(DEPTH.cardDrag);
    scene2.tweens.add({
      targets: spr,
      x: to.x,
      y: to.y,
      scaleX: toScale,
      scaleY: toScale,
      duration: FLY_MS,
      delay,
      ease: "Cubic.Out",
      // Spark wake behind the card — shed from 7 points spanning its full height, so the trail is as tall
      // as the card. Height comes from the layout data, not the sprite: makeCardSprite returns a Container,
      // whose displayHeight is meaningless. The shared emitter lives in render/particles, so four staggered
      // combo flights all trail off one pool.
      onUpdate: () => cardTrail(spr.x, spr.y, TABLE.card.h * spr.scaleY),
      // wake tracks the shrinking card
      // Touchdown: a short squash-and-settle on the spot it lands, THEN hand the card to the board's
      // discard conveyor. Without it the flight simply stops dead — the motion has no arrival. The
      // overlay sprite outlives the flight by exactly this beat; the conveyor takes over after it.
      onComplete: () => {
        cardImpact(to.x, to.y, TABLE.card.h * toScale);
        scene2.tweens.add({
          targets: spr,
          scaleX: toScale * PUNCH,
          scaleY: toScale * (2 - PUNCH),
          // squash: wider means flatter, so it reads as weight, not growth
          duration: PUNCH_MS,
          yoyo: true,
          ease: "Quad.Out",
          onComplete: () => {
            spr.destroy();
            emit("discard:landed", { card });
          }
        });
      }
    });
  }
  const handPoint = (side) => ({ x: TABLE.hand[slotOf(side)].anchorX, y: TABLE.hand[slotOf(side)].y });
  const discardPoint = { x: TABLE.pile.discard.x, y: TABLE.pile.discard.y };
  on(
    "combo:played",
    ({ side, cards }) => cards.forEach((card, k2) => fly(card, handPoint(side), discardPoint, k2 * COMBO_STAGGER, slotScale(side)))
  );
}

