function columnBadge(scene2, x, cy, half, depth, dim, above = false) {
  const C = rewardColMock();
  const txt = scene2.add.text(x, cy + (above ? -1 : 1) * (half + us(11)), "", C ? { fontSize: `${C.font}px`, color: "#000000", fontStyle: "bold" } : { fontSize: uf(13), color: dim }).setOrigin(0.5).setDepth(depth + 2);
  if (!C) txt.setStroke("#14110f", 4);
  const [tw, th, tdy] = C?.tag ?? [0, 0, 0];
  if (C) tagTex(scene2, tw, th);
  const tag = C ? scene2.add.image(x, cy + tdy, TAG_KEY).setOrigin((TAG_M + tw / 2) / (tw + 2 * TAG_M + TAG_SH), (TAG_M + th / 2) / (th + 2 * TAG_M + TAG_SH)).setDepth(depth + 1) : null;
  const sizeTag = (w) => {
    tag.setScale(w / tw / TAG_K, 1 / TAG_K);
  };
  if (C) sizeTag(tw);
  let shown = true;
  let onTag = false;
  let [ox, oy] = [0, 0];
  const paint = () => {
    txt.setVisible(shown);
    tag?.setVisible(shown && onTag);
  };
  const place = () => {
    if (!C) return;
    txt.setPosition(x + ox, oy + (onTag ? cy + tdy : above ? cy - half - C.font * 0.6 : cy + C.timerDy));
    tag?.setPosition(x + ox, cy + tdy + oy);
  };
  return {
    set(text, claim) {
      txt.setText(text);
      if (!C) {
        txt.setColor(claim ? "#ffd54a" : dim);
        return;
      }
      onTag = claim && text !== "";
      txt.setFontSize(onTag ? C.font : C.timerFont);
      place();
      if (onTag) sizeTag(Math.max(tw, txt.width + 16));
      paint();
    },
    setVisible(v) {
      shown = v;
      paint();
    },
    shift(dx, dy) {
      [ox, oy] = [dx, dy];
      place();
    }
  };
}

