// src/render/rate-us-popup.ts
function buildRatePopup(scene2) {
  const col15 = TABLE.color;
  const CARD_W6 = us(460);
  const CARD_H4 = us(280);
  const pop = buildPopup(scene2, {
    depth: DEPTH.modal + 40,
    // over the menu, like the what's-new explainer
    card: { w: CARD_W6, h: CARD_H4, frame: true },
    titleKey: "rate.title",
    onDimClick: () => {
      snoozeRating();
      pop.setOpen(false);
    }
  });
  const body = scene2.add.text(W / 2, H / 2 - us(24), t("rate.body"), {
    fontSize: uf(17),
    color: INK.text,
    align: "center",
    lineSpacing: us(5),
    wordWrap: { width: CARD_W6 - us(76) }
  });
  body.setOrigin(0.5);
  pop.add(body);
  on("i18n:changed", () => body.setText(t("rate.body")));
  function btn(dx, dy, key2, fill, tex, onTap) {
    const b = makeButton(scene2, {
      x: W / 2 + dx,
      y: H / 2 + dy,
      w: us(170),
      h: us(44),
      base: fill,
      frameTex: tex,
      frameInset: us(12),
      key: key2,
      color: col15.text,
      onClick: () => {
        pop.setOpen(false);
        onTap();
      },
      container: pop.root
    });
    pop.track(b);
  }
  btn(0, us(46), "rate.yes", col15.btnReady, "ui-btn-green", () => {
    gaDesign("rate:yes");
    markRated("rated");
    openStoreListing();
  });
  btn(us(-95), us(100), "rate.later", col15.btnIdle, "ui-btn-blue", () => {
    gaDesign("rate:later");
    snoozeRating();
  });
  btn(us(95), us(100), "rate.never", col15.cardBack, "ui-btn-red", () => {
    gaDesign("rate:never");
    markRated("never");
  });
  pop.setOpen(false);
  return { open: () => pop.setOpen(true) };
}

