// src/render/roll-number.ts
init_define_PG_BANNERS();
var MS_PER_UNIT = 18;
function rollNumber(scene2, obj, to, fmt2 = String) {
  const from = obj.getData("rollVal");
  obj.setData("rollVal", to);
  obj.getData("rollTween")?.remove();
  if (from === void 0 || from === to) {
    obj.setText(fmt2(to));
    return;
  }
  const tw = scene2.tweens.addCounter({
    from,
    to,
    duration: Math.min(700, 120 + Math.abs(to - from) * MS_PER_UNIT),
    ease: "Sine.Out",
    // The counter drives a VALUE, not `obj` — killTweensOf(obj) can't reach it, so a HUD rebuilt mid-roll
    // would leave this writing into a destroyed Text (which throws inside TweenManager.update and takes
    // the rest of the scene step, input included, with it). Drop the roll instead.
    onUpdate: (t2) => obj.scene ? obj.setText(fmt2(Math.round(t2.getValue()))) : tw.remove(),
    onComplete: () => obj.scene && obj.setText(fmt2(to))
  });
  obj.setData("rollTween", tw);
}

