  const status = scene2.add.text(cx - ms2(CARD_W3 / 2) + ms2(70), cy - ms2(CARD_H2 / 2) + ms2(52), "", { fontSize: mf(24), color: inkHi("#e0b52c"), fontStyle: "bold" }).setOrigin(0.5);
