    const returning0 = adventureSlot() !== null;
    const day = daily ? utcDay() : returning0 ? progress.day : void 0;
    const side = day ? false : wonder ?? (returning0 ? progress.wonder === true : false);
    if (CHAPTERS.some((ch) => ch.id === chapter2)) progress = switchChapter(progress, chapter2, side, day);
