// src/adventure-timers.ts
init_define_PG_BANNERS();
var AD_COOLDOWN_KEY = "sd2d.ad-cooldowns";
function loadAdCooldowns() {
  const raw2 = storageGet(AD_COOLDOWN_KEY);
  if (!raw2) return {};
  try {
    const o = JSON.parse(raw2);
    const out = {};
    for (const k2 of ["coins", "emeralds", "chest"]) {
      const v = o[k2];
      if (typeof v === "number" && v >= 0) out[k2] = v;
    }
    return out;
  } catch {
    return {};
  }
}
function adOfferReadyIn(offer, nowMs) {
  const last = loadAdCooldowns()[offer];
  if (last === void 0) return 0;
  const elapsed = (nowMs - last) / 1e3;
  return Math.max(0, Math.ceil(AD_COOLDOWN[offer] - elapsed));
}
function markAdClaimed(offer, nowMs) {
  const cd = loadAdCooldowns();
  cd[offer] = nowMs;
  try {
    storageSet(AD_COOLDOWN_KEY, JSON.stringify(cd));
  } catch {
  }
}

