        v.wearLine.setText(`${cur2}/${item.dur.max}`).setVisible(true);
        const due = repairDue(item);
        const repairable = canRepair(item);
        const rCost = repairable ? repairCost(item) : null;
        const afford = !!rCost && ld.coins >= rCost.coins && loadEmeralds() >= rCost.emeralds;
        const showBtn = !!rCost && due && repairable;
        v.repairBtn?.setVisible(showBtn);
